procedure:public.cleanup_audit_logs(inte.source_code:
declare
  v_deleted int;
begin
  delete from public.audit_logs
  where created_at < now() - (p_retention_days || ' days')::interval;

  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

